import { describe, expect, it } from 'vitest';
import {
  nestedCheckout,
  useGitCheckouts,
} from '../../../../core/diff/git/test-support/git-checkout.mjs';
import { useGitFixtures } from '../../../../core/diff/git/test-support/git-repository.mjs';
import { hasGeneratorMarker } from '../../../../shared/conventions/generator-marker.mjs';
import { markedGeneratedFiles } from './generated-files.mjs';

const { createGitRepository } = useGitFixtures();
const { gitCheckout } = useGitCheckouts();

describe('hasGeneratorMarker', () => {
  it.each([
    '// @generated by protoc-gen-ts\n',
    '// Code generated by sqlc. DO NOT EDIT.\n',
    '/* eslint-disable */\n// This file was automatically generated.\n',
    '// <auto-generated />\n',
  ])('finds the marker in the first lines: %s', (text) => {
    expect(hasGeneratorMarker(text)).toBe(true);
  });

  it('ignores a file without one, or with one below the first lines', () => {
    expect(hasGeneratorMarker('export const generated = 1;\n')).toBe(false);
    expect(hasGeneratorMarker(`${'\n'.repeat(6)}// @generated\n`)).toBe(false);
  });
});

describe('markedGeneratedFiles', () => {
  it('lists the files named like generated code that carry a marker, and any file with a known generator header', () => {
    const { root } = createGitRepository({
      'src/api.gen.ts': '// @generated\nexport {};\n',
      'src/big.gen.ts': 'export {};\n',
      'generated/client.ts': '// Code generated by openapi. DO NOT EDIT.\nexport {};\n',
      'src/hand.ts': '// @generated\nexport {};\n',
      'src/api/pets.ts':
        '/* eslint-disable */\n/**\n * NOTE: This class is auto generated by OpenAPI Generator (https://openapi-generator.tech).\n */\nexport {};\n',
      'src/proto/orders.ts': '// Code generated by protoc-gen-ts_proto. DO NOT EDIT.\nexport {};\n',
      'src/notes.ts': '/** Notes on the auto-generated ids. DO NOT EDIT by hand. */\nexport {};\n',
    });

    expect(markedGeneratedFiles(root).toSorted()).toEqual([
      'generated/client.ts',
      'src/api.gen.ts',
      'src/api/pets.ts',
      'src/proto/orders.ts',
    ]);
  });

  it('leaves out ignored folders and nested checkouts', () => {
    const marked = '// @generated\nexport {};\n';
    const root = gitCheckout(
      {
        'src/api.gen.ts': marked,
        'scratch/other.gen.ts': marked,
        ...nestedCheckout('.claude/worktrees/x', { 'src/nested.gen.ts': marked }),
      },
      ['scratch/'],
    );

    expect(markedGeneratedFiles(root)).toEqual(['src/api.gen.ts']);
  });

  it('lists nothing for a folder outside Git without files', () => {
    expect(markedGeneratedFiles(gitCheckout({}))).toEqual([]);
  });
});
